/* =========================================================
   Studio Karya Nusa — custom theme styles
   Theme: Twenty Twenty-One
   ========================================================= */

:root {
	--skn-green: #123b32;
	--skn-green-deep: #0c2a24;
	--skn-cream: #f7f1e6;
	--skn-cream-soft: #fbf7ef;
	--skn-terra: #d97757;
	--skn-mustard: #e3b23c;
	--skn-ink: #1f2421;
	--skn-muted: #5e6a63;
	--skn-line: rgba(18, 59, 50, 0.16);
	--skn-serif: Georgia, "Times New Roman", serif;
	--skn-sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;

	--global--color-primary: var(--skn-green);
	--global--color-primary-hover: var(--skn-terra);
	--global--color-background: var(--skn-cream);
	--global--color-secondary: var(--skn-terra);
	--global--color-border: var(--skn-line);
	--global--font-primary: var(--skn-serif);
	--global--font-secondary: var(--skn-sans);
	--branding--title--font-family: var(--skn-serif);
	--branding--description--font-family: var(--skn-sans);
	--entry-header--font-family: var(--skn-serif);
	--footer--color-text: var(--skn-cream);
}

html {
	scroll-behavior: smooth;
}

body {
	background: var(--skn-cream);
	color: var(--skn-ink);
	font-family: var(--skn-sans);
	font-size: 17px;
	line-height: 1.75;
	-webkit-font-smoothing: antialiased;
}

::selection {
	background: var(--skn-terra);
	color: var(--skn-cream);
}

h1, h2, h3, h4, h5, h6,
.site-title,
.entry-title,
.page-title {
	font-family: var(--skn-serif);
	color: var(--skn-green);
	line-height: 1.08;
	letter-spacing: -0.02em;
}

a {
	color: var(--skn-green);
	text-decoration-thickness: 1px;
	text-underline-offset: 3px;
}

a:hover,
a:focus {
	color: var(--skn-terra);
}

/* ---------------------------------------------------------
   Header
   --------------------------------------------------------- */

.site-header {
	max-width: 1240px !important;
	margin: 0 auto !important;
	padding: 22px 32px !important;
	display: flex !important;
	align-items: center;
	gap: 18px;
	position: sticky;
	top: 0;
	z-index: 100;
	background: rgba(247, 241, 230, 0.96);
	backdrop-filter: blur(12px);
	border-bottom: 1px solid var(--skn-line);
}

.site-header > .site-logo {
	width: auto !important;
	padding: 0 !important;
	border: 0 !important;
	margin: 0 !important;
	flex: 0 0 auto;
}

.site-header .custom-logo {
	width: 54px;
	height: 54px;
	max-height: 54px;
	max-width: 54px;
	object-fit: contain;
	border-radius: 50%;
}

.site-branding {
	margin: 0 !important;
	flex: 1 1 auto;
	min-width: 0;
}

.site-title {
	font-size: 26px !important;
	line-height: 1.05 !important;
	margin: 0 !important;
	letter-spacing: -0.02em;
}

.site-title a {
	color: var(--skn-green) !important;
	text-decoration: none;
}

.site-description {
	margin: 5px 0 0 !important;
	font-size: 11px !important;
	letter-spacing: 0.16em;
	text-transform: uppercase;
	color: var(--skn-muted) !important;
	line-height: 1.4;
}

.primary-navigation {
	margin-left: auto;
}

@media only screen and (min-width: 822px) {
	#primary-menu-list {
		display: flex;
		align-items: center;
		gap: 28px;
		margin: 0;
		padding: 0;
		list-style: none;
	}

	#primary-menu-list li {
		margin: 0;
	}

	#primary-menu-list a {
		font-size: 12px;
		font-weight: 600;
		letter-spacing: 0.12em;
		text-transform: uppercase;
		text-decoration: none;
		color: var(--skn-green);
		padding: 6px 0;
		position: relative;
	}

	#primary-menu-list a::after {
		content: "";
		position: absolute;
		left: 0;
		right: 0;
		bottom: 0;
		height: 2px;
		background: var(--skn-terra);
		transform: scaleX(0);
		transform-origin: left;
		transition: transform 0.2s ease;
	}

	#primary-menu-list a:hover::after,
	#primary-menu-list .current-menu-item > a::after {
		transform: scaleX(1);
	}

	#primary-menu-list .current-menu-item > a {
		color: var(--skn-terra);
	}

	.menu-button-container {
		display: none;
	}
}

/* ---------------------------------------------------------
   Home layout
   --------------------------------------------------------- */

body.home .site-content {
	padding: 0 !important;
}

body.home .content-area,
body.home .site-main {
	margin: 0 !important;
	padding: 0 !important;
}

body.home .entry-content {
	max-width: none !important;
	margin: 0 !important;
	padding: 0 !important;
}

body.home .entry-content > * {
	max-width: none !important;
	margin-left: 0 !important;
	margin-right: 0 !important;
}

body.home .entry-content .wp-block-group__inner-container > *,
body.home .entry-content .wp-block-columns,
body.home .entry-content .wp-block-column,
body.home .entry-content .wp-block-latest-posts {
	max-width: none !important;
}

.skn-container {
	max-width: 1200px !important;
	margin-left: auto !important;
	margin-right: auto !important;
	padding-left: 32px;
	padding-right: 32px;
	box-sizing: border-box;
}

.skn-container > .wp-block-group__inner-container > * {
	max-width: none !important;
	margin-left: 0 !important;
	margin-right: 0 !important;
}

/* ---------------------------------------------------------
   Hero
   --------------------------------------------------------- */

.skn-hero {
	background:
		radial-gradient(circle at 82% 18%, rgba(227, 178, 60, 0.18), transparent 32%),
		radial-gradient(circle at 12% 88%, rgba(217, 119, 87, 0.16), transparent 36%),
		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green) 60%, #1b4d42);
	color: var(--skn-cream);
	padding: 92px 0 96px;
	position: relative;
	overflow: hidden;
}

.skn-hero::before {
	content: "";
	position: absolute;
	inset: 0;
	background-image: radial-gradient(rgba(247, 241, 230, 0.08) 1px, transparent 1px);
	background-size: 26px 26px;
	opacity: 0.35;
	pointer-events: none;
}

.skn-hero-inner {
	position: relative;
	z-index: 1;
}

.skn-hero-cols {
	align-items: center;
	gap: 48px;
}

.skn-hero-copy {
	padding-right: 20px;
}

.skn-hero-kicker {
	font-size: 11px;
	letter-spacing: 0.24em;
	text-transform: uppercase;
	color: var(--skn-mustard);
	margin: 0 0 18px;
	font-weight: 700;
}

.skn-hero-title {
	font-size: clamp(56px, 7vw, 104px) !important;
	line-height: 0.92 !important;
	color: var(--skn-cream) !important;
	margin: 0 0 22px !important;
	letter-spacing: -0.045em !important;
}

.skn-hero-tagline {
	font-family: var(--skn-serif);
	font-size: clamp(22px, 2.4vw, 32px);
	font-style: italic;
	color: var(--skn-cream) !important;
	margin: 0 0 18px;
	line-height: 1.2;
}

.skn-hero-text {
	font-size: 17px;
	line-height: 1.75;
	color: rgba(247, 241, 230, 0.78);
	max-width: 520px;
	margin: 0 0 32px;
}

.skn-hero-buttons {
	gap: 14px;
}

.skn-btn .wp-block-button__link {
	border-radius: 999px;
	padding: 14px 26px;
	font-size: 12px;
	font-weight: 700;
	letter-spacing: 0.12em;
	text-transform: uppercase;
	text-decoration: none;
	transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.skn-hero-buttons .skn-btn-primary .wp-block-button__link,
.skn-hero-buttons .skn-btn-primary .wp-block-button__link:not(:hover):not(:active) {
	background-color: var(--skn-terra) !important;
	color: var(--skn-cream) !important;
	border-color: var(--skn-terra) !important;
}

.skn-hero-buttons .skn-btn-primary .wp-block-button__link:hover {
	background-color: var(--skn-mustard) !important;
	color: var(--skn-green-deep) !important;
	border-color: var(--skn-mustard) !important;
	transform: translateY(-2px);
}

.skn-hero-buttons .skn-btn-ghost .wp-block-button__link,
.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:not(:hover):not(:active) {
	background-color: transparent !important;
	color: var(--skn-cream) !important;
	border-color: rgba(247, 241, 230, 0.45) !important;
}

.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:hover {
	background-color: var(--skn-cream) !important;
	color: var(--skn-green) !important;
	border-color: var(--skn-cream) !important;
	transform: translateY(-2px);
}

.skn-hero-visual {
	display: flex;
	justify-content: flex-end;
}

.skn-hero-poster {
	margin: 0 !important;
	width: min(100%, 420px);
	transform: rotate(2.5deg);
}

.skn-hero-poster img {
	width: 100%;
	height: auto;
	border: 10px solid var(--skn-cream);
	border-radius: 6px;
	box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);
	display: block;
}

/* ---------------------------------------------------------
   Values
   --------------------------------------------------------- */

.skn-values {
	background: var(--skn-cream);
	padding: 64px 0 56px;
	border-bottom: 1px solid var(--skn-line);
}

.skn-values-grid {
	gap: 0;
}

.skn-values-grid .wp-block-column {
	padding: 0 28px;
	border-left: 1px solid var(--skn-line);
}

.skn-values-grid .wp-block-column:first-child {
	border-left: 0;
	padding-left: 0;
}

.skn-value-num {
	font-family: var(--skn-serif);
	font-size: 14px;
	color: var(--skn-terra);
	letter-spacing: 0.1em;
	margin: 0 0 10px;
}

.skn-value-title {
	font-size: 30px !important;
	margin: 0 0 8px !important;
}

.skn-values p {
	font-size: 15px;
	color: var(--skn-muted);
	margin: 0;
	line-height: 1.65;
}

/* ---------------------------------------------------------
   Programs
   --------------------------------------------------------- */

.skn-programs {
	background: var(--skn-cream-soft);
	padding: 96px 0;
}

.skn-section-head {
	max-width: 720px !important;
	margin: 0 0 44px !important;
}

.skn-kicker {
	font-size: 11px;
	font-weight: 700;
	letter-spacing: 0.24em;
	text-transform: uppercase;
	color: var(--skn-terra);
	margin: 0 0 12px;
}

.skn-section-title {
	font-size: clamp(36px, 4vw, 56px) !important;
	margin: 0 0 16px !important;
}

.skn-section-lead {
	font-size: 17px;
	color: var(--skn-muted);
	line-height: 1.7;
	margin: 0;
	max-width: 620px;
}

.skn-card-grid {
	gap: 24px;
	align-items: stretch;
}

.skn-card-grid .wp-block-column {
	display: flex;
}

.skn-card {
	background: var(--skn-cream);
	border: 1px solid var(--skn-line);
	border-radius: 18px;
	padding: 30px 28px 26px !important;
	width: 100%;
	display: flex;
	flex-direction: column;
	transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}

.skn-card:hover {
	transform: translateY(-6px);
	box-shadow: 0 18px 40px rgba(18, 59, 50, 0.1);
	border-color: rgba(217, 119, 87, 0.45);
}

.skn-card-num {
	font-family: var(--skn-serif);
	font-size: 13px;
	letter-spacing: 0.12em;
	color: var(--skn-terra);
	margin: 0 0 22px;
}

.skn-card h3 {
	font-size: 25px !important;
	margin: 0 0 10px !important;
	line-height: 1.15 !important;
}

.skn-card p {
	font-size: 15px;
	color: var(--skn-muted);
	margin: 0 0 18px;
	line-height: 1.65;
}

.skn-card-link {
	margin-top: auto !important;
}

.skn-card-link a,
.skn-section-link a {
	font-size: 12px;
	font-weight: 700;
	letter-spacing: 0.1em;
	text-transform: uppercase;
	text-decoration: none;
	color: var(--skn-terra);
	border-bottom: 1px solid rgba(217, 119, 87, 0.4);
	padding-bottom: 2px;
}

.skn-card-link a:hover,
.skn-section-link a:hover {
	color: var(--skn-green);
	border-color: var(--skn-green);
}

/* ---------------------------------------------------------
   Works
   --------------------------------------------------------- */

.skn-works {
	background: var(--skn-cream);
	padding: 96px 0;
}

.skn-works-grid {
	gap: 56px;
}

.skn-works .skn-section-title {
	font-size: clamp(34px, 4vw, 52px) !important;
}

.skn-latest {
	display: block !important;
	margin: 0 !important;
	padding: 0 !important;
	list-style: none !important;
}

.skn-latest li {
	background: #fffaf2;
	border: 1px solid var(--skn-line);
	border-radius: 20px;
	overflow: hidden;
	padding: 0 !important;
	margin: 0 !important;
	box-shadow: 0 18px 50px rgba(18, 59, 50, 0.08);
	display: grid;
	grid-template-columns: 42% 1fr;
	align-items: stretch;
}

.skn-latest .wp-block-latest-posts__featured-image {
	margin: 0 !important;
	grid-row: 1 / span 2;
	background: var(--skn-green);
	padding: 18px;
	display: flex;
	align-items: center;
	justify-content: center;
}

.skn-latest .wp-block-latest-posts__featured-image img {
	width: 100% !important;
	height: auto !important;
	max-height: 420px;
	object-fit: contain;
	display: block;
	box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);
}

.skn-latest .wp-block-latest-posts__post-title {
	display: block;
	font-family: var(--skn-serif);
	font-size: 30px;
	line-height: 1.15;
	color: var(--skn-green);
	text-decoration: none;
	padding: 28px 30px 0;
}

.skn-latest .wp-block-latest-posts__post-title:hover {
	color: var(--skn-terra);
}

.skn-latest .wp-block-latest-posts__post-excerpt {
	font-size: 15px;
	color: var(--skn-muted);
	line-height: 1.65;
	padding: 10px 30px 28px;
	margin: 0 !important;
}

/* ---------------------------------------------------------
   Agenda
   --------------------------------------------------------- */

.skn-agenda {
	background:
		radial-gradient(circle at 90% 10%, rgba(227, 178, 60, 0.16), transparent 30%),
		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green));
	color: var(--skn-cream);
	padding: 96px 0;
}

.skn-agenda .skn-section-title {
	color: var(--skn-cream) !important;
}

.skn-agenda .skn-kicker {
	color: var(--skn-mustard);
}

.skn-agenda .skn-section-lead {
	color: rgba(247, 241, 230, 0.75);
}

.skn-agenda .skn-section-link a {
	color: var(--skn-mustard);
	border-color: rgba(227, 178, 60, 0.5);
}

.skn-agenda .skn-section-link a:hover {
	color: var(--skn-cream);
	border-color: var(--skn-cream);
}

.skn-latest-agenda li {
	background: #fffaf2;
}

/* ---------------------------------------------------------
   CTA
   --------------------------------------------------------- */

.skn-cta {
	background:
		radial-gradient(circle at 15% 20%, rgba(247, 241, 230, 0.12), transparent 30%),
		var(--skn-terra);
	color: var(--skn-cream);
	padding: 88px 0;
	text-align: center;
}

.skn-cta-inner {
	max-width: 820px !important;
}

.skn-cta .skn-kicker {
	color: var(--skn-green-deep);
}

.skn-cta-title {
	font-size: clamp(40px, 5vw, 64px) !important;
	color: var(--skn-cream) !important;
	margin: 0 0 16px !important;
}

.skn-cta-text {
	font-size: 18px;
	color: rgba(247, 241, 230, 0.85);
	max-width: 620px;
	margin: 0 auto 28px;
}

.skn-cta-actions {
	margin: 0 0 24px !important;
}

.skn-cta-button {
	display: inline-block;
	background: var(--skn-cream);
	color: var(--skn-green) !important;
	border-radius: 999px;
	padding: 14px 30px;
	font-size: 12px;
	font-weight: 700;
	letter-spacing: 0.12em;
	text-transform: uppercase;
	text-decoration: none;
	transition: transform 0.2s ease, background 0.2s ease;
}

.skn-cta-button:hover {
	background: var(--skn-green);
	color: var(--skn-cream) !important;
	transform: translateY(-2px);
}

.skn-cta-location {
	font-size: 11px;
	letter-spacing: 0.18em;
	text-transform: uppercase;
	color: rgba(247, 241, 230, 0.65);
	margin: 0;
}

/* ---------------------------------------------------------
   Required pages
   --------------------------------------------------------- */

.page .site-main,
.single .site-main {
	padding-top: 0;
}

.page .entry-header,
.single .entry-header {
	max-width: 900px !important;
	margin: 56px auto 0 !important;
	padding: 0 32px !important;
}

.page .entry-title,
.single .entry-title {
	font-size: clamp(42px, 6vw, 72px) !important;
	line-height: 0.98 !important;
	margin: 0 !important;
	color: var(--skn-green);
}

.page .entry-content,
.single .entry-content {
	max-width: 760px !important;
	margin: 32px auto 72px !important;
	padding: 0 32px !important;
}

.page .entry-content > *,
.single .entry-content > * {
	max-width: none !important;
	margin-left: 0 !important;
	margin-right: 0 !important;
}

.page .entry-content .wp-block-group__inner-container > *,
.single .entry-content .wp-block-group__inner-container > * {
	max-width: none !important;
	margin-left: 0 !important;
	margin-right: 0 !important;
}

.skn-required-page {
	position: relative;
}

.skn-page-heading {
	font-size: clamp(34px, 4.5vw, 52px) !important;
	margin: 0 0 18px !important;
}

.skn-lead {
	font-size: 20px !important;
	line-height: 1.7 !important;
	color: var(--skn-ink) !important;
}

.skn-note-line {
	background: #fffaf2;
	border-left: 4px solid var(--skn-terra);
	border-radius: 0 12px 12px 0;
	padding: 16px 20px !important;
	font-size: 16px !important;
	font-weight: 600;
	color: var(--skn-green) !important;
	margin: 28px 0 0 !important;
}

.skn-verify-line {
	border-left-color: var(--skn-mustard);
	background: var(--skn-green);
	color: var(--skn-cream) !important;
	font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
	letter-spacing: 0.02em;
}

.skn-verify-line::before {
	content: "✓ ";
	color: var(--skn-mustard);
}

/* ---------------------------------------------------------
   Single posts
   --------------------------------------------------------- */

.single .entry-header .post-thumbnail {
	display: none !important;
}

.single .entry-content p {
	font-size: 18px;
	line-height: 1.85;
}

.skn-post-image {
	margin: 36px 0 !important;
}

.skn-post-image img {
	border-radius: 16px;
	box-shadow: 0 20px 50px rgba(18, 59, 50, 0.15);
}

.skn-schedule-line {
	background: #fffaf2;
	border-left: 4px solid var(--skn-mustard);
	border-radius: 0 12px 12px 0;
	padding: 16px 20px !important;
	font-weight: 700;
	color: var(--skn-green) !important;
	margin-top: 28px !important;
}

.single .entry-footer {
	max-width: 760px !important;
	margin: 0 auto 72px !important;
	padding: 24px 32px 0 !important;
	border-top: 1px solid var(--skn-line);
	font-size: 13px;
	color: var(--skn-muted);
}

.single .entry-footer .posted-by {
	margin-bottom: 8px;
}

.single .entry-footer .post-taxonomies {
	margin-top: 8px;
}

.single .entry-footer a {
	color: var(--skn-terra);
	text-decoration: none;
}

.single .author-bio {
	max-width: 760px !important;
	margin: 0 auto 72px !important;
	padding: 0 32px !important;
}

/* ---------------------------------------------------------
   Blog & archives
   --------------------------------------------------------- */

.blog .site-main,
.archive .site-main {
	max-width: 1100px !important;
	margin: 0 auto !important;
	padding: 0 32px 80px !important;
}

.blog .page-header,
.archive .page-header {
	max-width: 100% !important;
	margin: 56px 0 32px !important;
	padding: 0 !important;
}

.blog .page-title,
.archive .page-title {
	font-size: clamp(36px, 4.5vw, 56px) !important;
	margin: 0 !important;
}

.archive .page-header .archive-description,
.archive .page-header .archive-description p {
	font-family: var(--skn-sans) !important;
	font-size: 17px !important;
	line-height: 1.7 !important;
	color: var(--skn-muted) !important;
	max-width: 720px;
	margin: 12px 0 0 !important;
}

.blog article,
.archive article {
	background: #fffaf2;
	border: 1px solid var(--skn-line);
	border-radius: 18px;
	padding: 24px !important;
	margin-bottom: 24px;
	display: grid;
	grid-template-columns: 200px 1fr;
	grid-template-rows: auto auto auto;
	gap: 0 28px;
	align-items: start;
	align-content: start;
}

.blog article .entry-header,
.archive article .entry-header {
	display: contents;
}

.blog article .entry-header .post-thumbnail,
.archive article .entry-header .post-thumbnail {
	grid-column: 1;
	grid-row: 1 / span 3;
	margin: 0 !important;
}

.blog article .entry-header .post-thumbnail img,
.archive article .entry-header .post-thumbnail img {
	border-radius: 12px;
	width: 100%;
	height: auto;
	max-height: 280px;
	object-fit: cover;
}

.blog article .entry-header .entry-title,
.archive article .entry-header .entry-title {
	grid-column: 2;
	grid-row: 1;
	font-size: 28px !important;
	margin: 0 !important;
	align-self: start;
}

.blog article .entry-header .entry-title a,
.archive article .entry-header .entry-title a {
	text-decoration: none;
}

.blog article .entry-header .entry-title a:hover,
.archive article .entry-header .entry-title a:hover {
	text-decoration: underline;
}

.blog article .entry-content,
.archive article .entry-content {
	grid-column: 2;
	grid-row: 2;
	margin: 8px 0 0 !important;
	max-width: none !important;
}

.blog article .entry-content p,
.archive article .entry-content p {
	font-size: 15px;
	color: var(--skn-muted);
	line-height: 1.65;
	margin: 0;
}

.blog article .entry-footer,
.archive article .entry-footer {
	grid-column: 2;
	grid-row: 3;
	margin: 12px 0 0 !important;
	padding: 0 !important;
	border: 0 !important;
	font-size: 12px;
	color: var(--skn-muted);
}

.blog article .entry-footer a,
.archive article .entry-footer a {
	color: var(--skn-terra);
	text-decoration: none;
}

/* ---------------------------------------------------------
   Footer
   --------------------------------------------------------- */

.site-footer {
	max-width: none !important;
	margin: 0 !important;
	padding: 48px 0 36px !important;
	background: var(--skn-green-deep);
	color: var(--skn-cream);
}

.site-footer > .footer-navigation,
.site-footer > .site-info {
	max-width: 1200px;
	margin-left: auto;
	margin-right: auto;
	padding-left: 32px;
	padding-right: 32px;
}

.site-footer .footer-navigation {
	text-align: left;
	margin: 0 0 20px;
}

.site-footer .footer-navigation-wrapper {
	display: flex;
	justify-content: flex-start !important;
	gap: 24px;
	list-style: none;
	margin: 0;
	padding: 0;
}

.site-footer .footer-navigation-wrapper li {
	line-height: 1.2;
	margin: 0;
}

.site-footer .footer-navigation-wrapper li a,
.site-footer .footer-navigation-wrapper li a:link,
.site-footer .footer-navigation-wrapper li a:visited,
.site-footer .footer-navigation-wrapper li a:active {
	color: rgba(247, 241, 230, 0.72) !important;
	font-size: 11px;
	letter-spacing: 0.14em;
	text-transform: uppercase;
	text-decoration: none;
	padding: 6px 0;
}

.site-footer .footer-navigation-wrapper li a:hover {
	color: var(--skn-mustard) !important;
}

.site-footer > .site-info {
	border-top: 1px solid rgba(247, 241, 230, 0.18);
	padding-top: 24px;
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16px;
}

.site-footer .site-info .site-name {
	font-family: var(--skn-serif);
	font-size: 18px;
}

.site-footer .site-info .site-logo .custom-logo {
	width: 44px;
	height: 44px;
	max-height: 44px;
}

.site-footer .powered-by,
.site-footer .privacy-policy {
	display: none !important;
}

.site-footer .site-info::after {
	content: "Ruang kreasi dan berbagi ide";
	font-size: 12px;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: rgba(247, 241, 230, 0.55);
}

/* ---------------------------------------------------------
   Responsive
   --------------------------------------------------------- */

@media (max-width: 1024px) {
	.skn-hero-title {
		font-size: clamp(48px, 8vw, 76px) !important;
	}

	.skn-hero-cols {
		gap: 32px;
	}

	.skn-hero-poster {
		width: min(100%, 340px);
	}

	.skn-latest li {
		grid-template-columns: 1fr;
	}

	.skn-latest .wp-block-latest-posts__featured-image {
		grid-row: auto;
	}

	.skn-latest .wp-block-latest-posts__featured-image img {
		max-height: 420px;
	}
}

@media (max-width: 821px) {
	.site-header {
		position: relative;
		flex-wrap: wrap;
		padding: 16px 20px !important;
		gap: 12px;
	}

	.site-header .custom-logo {
		width: 44px;
		height: 44px;
	}

	.site-title {
		font-size: 22px !important;
	}

	.site-description {
		font-size: 10px !important;
	}

	.primary-navigation {
		width: 100%;
		margin-left: 0;
	}

	.skn-container {
		padding-left: 20px;
		padding-right: 20px;
	}

	.skn-hero {
		padding: 56px 0 64px;
	}

	.skn-hero-cols {
		flex-direction: column;
	}

	.skn-hero-copy {
		padding-right: 0;
	}

	.skn-hero-visual {
		justify-content: flex-start;
		margin-top: 32px;
	}

	.skn-hero-poster {
		width: min(100%, 320px);
		transform: rotate(1.5deg);
	}

	.skn-values {
		padding: 40px 0;
	}

	.skn-values-grid .wp-block-column {
		border-left: 0;
		border-top: 1px solid var(--skn-line);
		padding: 20px 0 0;
		margin-top: 20px;
	}

	.skn-values-grid .wp-block-column:first-child {
		border-top: 0;
		margin-top: 0;
		padding-top: 0;
	}

	.skn-programs,
	.skn-works,
	.skn-agenda {
		padding: 64px 0;
	}

	.skn-card-grid {
		flex-direction: column;
	}

	.skn-card-grid .wp-block-column {
		width: 100%;
	}

	.skn-works-grid,
	.skn-agenda-grid {
		flex-direction: column;
		gap: 32px;
	}

	.skn-works-grid .wp-block-column,
	.skn-agenda-grid .wp-block-column {
		width: 100% !important;
		flex-basis: 100% !important;
	}

	.skn-latest li {
		grid-template-columns: 1fr;
	}

	.skn-latest .wp-block-latest-posts__featured-image {
		grid-row: auto;
	}

	.skn-latest .wp-block-latest-posts__featured-image img {
		max-height: 380px;
	}

	.skn-cta {
		padding: 64px 0;
	}

	.page .entry-header,
	.single .entry-header {
		margin-top: 32px !important;
		padding: 0 20px !important;
	}

	.page .entry-content,
	.single .entry-content {
		padding: 0 20px !important;
		margin-top: 24px !important;
	}

	.page .entry-title,
	.single .entry-title {
		font-size: clamp(34px, 9vw, 48px) !important;
	}

	.blog .site-main,
	.archive .site-main {
		padding: 0 20px 64px !important;
	}

	.blog article,
	.archive article {
		grid-template-columns: 1fr;
		padding: 20px !important;
	}

	.blog article .entry-header,
	.archive article .entry-header {
		display: block;
	}

	.blog article .entry-header .post-thumbnail,
	.archive article .entry-header .post-thumbnail {
		margin-bottom: 16px !important;
	}

	.blog article .entry-header .entry-title,
	.archive article .entry-header .entry-title {
		font-size: 26px !important;
	}

	.site-footer > .footer-navigation,
	.site-footer > .site-info {
		padding-left: 20px;
		padding-right: 20px;
	}

	.site-footer > .site-info {
		flex-direction: column;
		align-items: flex-start;
	}

	.site-footer .site-info::after {
		margin-top: 8px;
	}
}
